def _decimal(digits):
    """Decimal value of a digit run, rejecting anything above 2**63-1.

    Leading zeros are permitted, so the length test runs on the stripped form
    (this also avoids CPython's 4300-digit int conversion guard).
    """
    stripped = digits.lstrip(b'0')
    if len(stripped) > 19:
        raise Malformed()
    number = int(stripped) if stripped else 0
    if number > MAX:
        raise Malformed()
    return number


def _hexadecimal(digits):
    if len(digits) > 16:
        raise Malformed()
    number = int(digits, 16)
    if number > MAX:
        raise Malformed()
    return number


def _content_length(fields):
    values = [value for name, value in fields
              if name.lower() == b'content-length']
    if not values:
        return None
    declared = None
    for value in values:
        for member in value.split(b','):
            member = member.strip(b' \t')
            if not member or member.translate(None, DIGITS):
                raise Malformed()
            number = _decimal(member)
            if declared is None:
                declared = number
            elif number != declared:
                raise Malformed()
    return declared


